import kotlinx.coroutines.*

suspend fun task(name: String, ms: Long): String {
    println("start $name")
    delay(ms)
    println("end $name")
    return name
}

fun main() = runBlocking {
    val x = async { task("x", 200) }.await()
    val y = async { task("y", 100) }
    println(x + y.await())
}

suspend fun sumAll(): Long {
    var s = 0L
    for (i in 1..2_000_000_000) s += i
    return s
}

// inside a ViewModel
fun refresh() = viewModelScope.launch {
    total.value = sumAll()
}
